import{_ as r,o as t,c as i,a2 as a}from"./chunks/framework.BXzK3EA4.js";const d=JSON.parse('{"title":"VPS Security Group User Guide","description":"","frontmatter":{"title":"VPS Security Group User Guide"},"headers":[],"relativePath":"operations-knowledge-base/vps/vps-security-group-user-guide.md","filePath":"operations-knowledge-base/vps/vps-security-group-user-guide.md","lastUpdated":1794292919000}'),o={name:"operations-knowledge-base/vps/vps-security-group-user-guide.md"};function s(n,e,l,u,c,p){return t(),i("div",null,[...e[0]||(e[0]=[a('<h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This document introduces the basic functions of VPS Security Groups, including how to create, associate, and manage security groups and security rules. It helps customers control network access to their VPS and improve server security.</p><p><strong>Supported Product:</strong></p><ul><li>VPS (Virtual Private Server)</li></ul><hr><h2 id="_1-what-is-a-security-group" tabindex="-1">1. What Is a Security Group? <a class="header-anchor" href="#_1-what-is-a-security-group" aria-label="Permalink to &quot;1. What Is a Security Group?&quot;">​</a></h2><p>A Security Group is a virtual firewall used to control network access to your VPS.</p><p>By configuring security group rules, you can control which IP addresses, protocols, and ports are allowed or denied access to your server, helping improve overall network security.</p><p>Common use cases include:</p><ul><li>Controlling inbound traffic</li><li>Controlling outbound traffic</li><li>Restricting access from specific IP addresses or IP ranges</li><li>Opening or closing specific service ports</li><li>Enhancing server security</li></ul><hr><h2 id="_2-security-group-overview" tabindex="-1">2. Security Group Overview <a class="header-anchor" href="#_2-security-group-overview" aria-label="Permalink to &quot;2. Security Group Overview&quot;">​</a></h2><p>When a VPS is created, the system automatically associates it with a default Security Group.</p><p>The default Security Group usually allows the basic remote access ports required to manage your server, including:</p><ul><li>SSH (Port 22)</li><li>Windows Remote Desktop (RDP, Port 3389)</li><li>ICMP (Ping)</li></ul><p>Therefore, in most cases, you can connect to your server immediately after deployment.</p><p><strong>Notes:</strong></p><ul><li>Each VPS can be associated with one Security Group.</li><li>Multiple Security Groups can be created within the same region.</li><li>One Security Group can be designated as the default Security Group for each region.</li><li>An associated Security Group can be detached or replaced at any time.</li></ul><hr><h2 id="_3-security-group-management" tabindex="-1">3. Security Group Management <a class="header-anchor" href="#_3-security-group-management" aria-label="Permalink to &quot;3. Security Group Management&quot;">​</a></h2><p>The platform provides two methods for managing Security Groups.</p><hr><h2 id="method-1-from-the-vps-management-page-recommended" tabindex="-1">Method 1: From the VPS Management Page (Recommended) <a class="header-anchor" href="#method-1-from-the-vps-management-page-recommended" aria-label="Permalink to &quot;Method 1: From the VPS Management Page (Recommended)&quot;">​</a></h2><p>This method is suitable for managing the Security Group of a specific VPS.</p><p><strong>Navigation:</strong></p><p><strong>Product Management → VPS → Security Group</strong></p><p>Available operations include:</p><ul><li>Enable Security Group</li><li>Disable Security Group</li><li>Create a Security Group</li><li>Associate a Security Group</li><li>Remove a Security Group Association</li><li>Manage Security Group Rules</li><li>Delete a Security Group</li></ul><p>This method is recommended when managing the network policy of an individual VPS.</p><hr><h2 id="method-2-global-security-group-management" tabindex="-1">Method 2: Global Security Group Management <a class="header-anchor" href="#method-2-global-security-group-management" aria-label="Permalink to &quot;Method 2: Global Security Group Management&quot;">​</a></h2><p>This method is suitable for centrally managing all Security Groups within the same region.</p><p><strong>Navigation:</strong></p><p><strong>Product Management → VPS → Security Group</strong></p><p>You can switch between different regions, such as:</p><ul><li>Hong Kong</li><li>Japan</li><li>Taiwan</li><li>Korea</li><li>Malaysia</li><li>Singapore</li><li>Silicon Valley</li><li>Los Angeles</li><li>Seattle</li></ul><p>Available operations include:</p><ul><li>Create Security Groups</li><li>Edit Security Groups</li><li>Delete Security Groups</li><li>Set the Default Security Group</li><li>Manage Security Group Rules</li></ul><p>This method is recommended for customers managing multiple VPS instances within the same region.</p><hr><h2 id="_4-creating-a-security-group" tabindex="-1">4. Creating a Security Group <a class="header-anchor" href="#_4-creating-a-security-group" aria-label="Permalink to &quot;4. Creating a Security Group&quot;">​</a></h2><p>Click <strong>Add</strong> to create a new Security Group.</p><p>When creating a Security Group, you need to specify:</p><ul><li>Security Group Name</li><li>Whether to set it as the Default Security Group</li></ul><p>After creation, the Security Group can be associated with one or more VPS instances.</p><hr><h2 id="_5-associating-or-removing-a-security-group" tabindex="-1">5. Associating or Removing a Security Group <a class="header-anchor" href="#_5-associating-or-removing-a-security-group" aria-label="Permalink to &quot;5. Associating or Removing a Security Group&quot;">​</a></h2><p>On the VPS Security Group page, you can associate an existing Security Group with your VPS.</p><p>Supported operations include:</p><h3 id="apply" tabindex="-1">Apply <a class="header-anchor" href="#apply" aria-label="Permalink to &quot;Apply&quot;">​</a></h3><p>Associates the selected Security Group with the current VPS.</p><h3 id="remove" tabindex="-1">Remove <a class="header-anchor" href="#remove" aria-label="Permalink to &quot;Remove&quot;">​</a></h3><p>Removes the Security Group association from the current VPS.</p><p><strong>Note:</strong></p><p>After removing the Security Group, the VPS will no longer be protected by its security rules. Ensure that appropriate firewall policies are configured within the operating system to avoid exposing your server to unnecessary security risks.</p><hr><h2 id="_6-managing-security-group-rules" tabindex="-1">6. Managing Security Group Rules <a class="header-anchor" href="#_6-managing-security-group-rules" aria-label="Permalink to &quot;6. Managing Security Group Rules&quot;">​</a></h2><p>Within the Security Group management page, you can add, edit, or delete security rules.</p><hr><h2 id="adding-a-security-rule" tabindex="-1">Adding a Security Rule <a class="header-anchor" href="#adding-a-security-rule" aria-label="Permalink to &quot;Adding a Security Rule&quot;">​</a></h2><p>Click <strong>Add</strong> and configure the following parameters:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td>Remote IP</td><td>The source IP address or CIDR block to allow or deny. For example, <code>0.0.0.0/0</code> allows access from all IP addresses.</td></tr><tr><td>Direction</td><td>Inbound or Outbound</td></tr><tr><td>Protocol</td><td>TCP, UDP, ICMP, etc.</td></tr><tr><td>Minimum Port</td><td>Starting port number</td></tr><tr><td>Maximum Port</td><td>Ending port number</td></tr></tbody></table><p><strong>Notes:</strong></p><ul><li>For a single port, set the minimum and maximum port to the same value (for example, <strong>22–22</strong>).</li><li>To allow a range of ports, specify the desired port range (for example, <strong>8000–8080</strong>).</li><li>Protocols such as ICMP do not require port numbers.</li></ul><hr><h2 id="editing-a-security-rule" tabindex="-1">Editing a Security Rule <a class="header-anchor" href="#editing-a-security-rule" aria-label="Permalink to &quot;Editing a Security Rule&quot;">​</a></h2><p>Click <strong>Edit</strong> to modify an existing rule.</p><p>You can update:</p><ul><li>Remote IP</li><li>Protocol</li><li>Direction</li><li>Port Range</li></ul><hr><h2 id="deleting-a-security-rule" tabindex="-1">Deleting a Security Rule <a class="header-anchor" href="#deleting-a-security-rule" aria-label="Permalink to &quot;Deleting a Security Rule&quot;">​</a></h2><p>Click <strong>Delete</strong> to remove a security rule.</p><p><strong>Note:</strong></p><p>After a rule is deleted, the corresponding network access will no longer be permitted according to that rule. Please ensure that removing the rule will not affect your services.</p><hr><h2 id="_7-common-use-cases" tabindex="-1">7. Common Use Cases <a class="header-anchor" href="#_7-common-use-cases" aria-label="Permalink to &quot;7. Common Use Cases&quot;">​</a></h2><h2 id="scenario-1-opening-website-ports" tabindex="-1">Scenario 1: Opening Website Ports <a class="header-anchor" href="#scenario-1-opening-website-ports" aria-label="Permalink to &quot;Scenario 1: Opening Website Ports&quot;">​</a></h2><p>After deploying a website, add inbound rules for:</p><ul><li>TCP Port 80 (HTTP)</li><li>TCP Port 443 (HTTPS)</li></ul><p>This allows users to access your website normally.</p><hr><h2 id="scenario-2-allowing-ssh-access" tabindex="-1">Scenario 2: Allowing SSH Access <a class="header-anchor" href="#scenario-2-allowing-ssh-access" aria-label="Permalink to &quot;Scenario 2: Allowing SSH Access&quot;">​</a></h2><p>Linux servers typically use:</p><ul><li>TCP Port 22</li></ul><p>If you change the SSH port, remember to update the Security Group accordingly.</p><hr><h2 id="scenario-3-allowing-windows-remote-desktop" tabindex="-1">Scenario 3: Allowing Windows Remote Desktop <a class="header-anchor" href="#scenario-3-allowing-windows-remote-desktop" aria-label="Permalink to &quot;Scenario 3: Allowing Windows Remote Desktop&quot;">​</a></h2><p>Windows servers typically use:</p><ul><li>TCP Port 3389</li></ul><p>If the Remote Desktop port has been changed, update the Security Group rules to match.</p><hr><h2 id="scenario-4-using-aapanel" tabindex="-1">Scenario 4: Using aaPanel <a class="header-anchor" href="#scenario-4-using-aapanel" aria-label="Permalink to &quot;Scenario 4: Using aaPanel&quot;">​</a></h2><p>After installing <strong>aaPanel</strong>, you must also allow the required ports in the Security Group; otherwise, the panel will not be accessible.</p><p>Common ports include:</p><ul><li>8888 (aaPanel)</li><li>80 (HTTP)</li><li>443 (HTTPS)</li></ul><p>Open additional ports as required by your services.</p><hr><h2 id="_8-frequently-asked-questions" tabindex="-1">8. Frequently Asked Questions <a class="header-anchor" href="#_8-frequently-asked-questions" aria-label="Permalink to &quot;8. Frequently Asked Questions&quot;">​</a></h2><h3 id="q1-what-happens-if-i-disable-the-security-group" tabindex="-1">Q1: What happens if I disable the Security Group? <a class="header-anchor" href="#q1-what-happens-if-i-disable-the-security-group" aria-label="Permalink to &quot;Q1: What happens if I disable the Security Group?&quot;">​</a></h3><p>Once the Security Group is disabled, the platform will no longer filter network traffic for your VPS.</p><p>It is recommended that you configure the operating system firewall to maintain proper security.</p><hr><h3 id="q2-why-can-t-i-access-a-service-after-opening-the-port" tabindex="-1">Q2: Why can&#39;t I access a service after opening the port? <a class="header-anchor" href="#q2-why-can-t-i-access-a-service-after-opening-the-port" aria-label="Permalink to &quot;Q2: Why can&#39;t I access a service after opening the port?&quot;">​</a></h3><p>Please verify the following:</p><ul><li>The Security Group allows the required port.</li><li>The operating system firewall allows the connection.</li><li>The service is running properly.</li><li>The service is listening on the correct port.</li></ul><hr><h3 id="q3-can-one-vps-be-associated-with-multiple-security-groups" tabindex="-1">Q3: Can one VPS be associated with multiple Security Groups? <a class="header-anchor" href="#q3-can-one-vps-be-associated-with-multiple-security-groups" aria-label="Permalink to &quot;Q3: Can one VPS be associated with multiple Security Groups?&quot;">​</a></h3><p>Currently, each VPS supports association with <strong>one Security Group only</strong>.</p><hr><h3 id="q4-can-security-groups-restrict-access-to-specific-ip-addresses" tabindex="-1">Q4: Can Security Groups restrict access to specific IP addresses? <a class="header-anchor" href="#q4-can-security-groups-restrict-access-to-specific-ip-addresses" aria-label="Permalink to &quot;Q4: Can Security Groups restrict access to specific IP addresses?&quot;">​</a></h3><p>Yes.</p><p>You can configure the <strong>Remote IP</strong> field to allow access only from specific IP addresses or CIDR ranges.</p><hr><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>⚠️ Security Groups are used to control network access to your VPS. Configure security rules carefully according to your business requirements.</p><p>⚠️ Modifying or deleting Security Group rules may affect the accessibility of your services. Verify the impact before making changes.</p><p>⚠️ If you change the listening port of a service, remember to update the corresponding Security Group rule.</p><p>⚠️ After deploying websites, databases, aaPanel, or other applications, make sure the required service ports are allowed in the Security Group; otherwise, the services may not be accessible.</p>',118)])])}const g=r(o,[["render",s]]);export{d as __pageData,g as default};
